/**
 * Deterministic extraction from a PDF's text layer. No model, no network.
 *
 * This is the engine that runs when no AI key is configured, and it is also
 * what the AI engine's answers are grounded against. It reads documents the
 * way a careful person would: find a label, take the amount printed beside
 * it; find the table, read its columns by their headings. It works on
 * digitally produced PDFs (the common case for pay applications generated by
 * accounting or billing software). It cannot read scans or see ink — and says
 * so instead of guessing.
 *
 * The rule throughout: when a value cannot be read reliably it is left empty
 * (null) or reported below the review threshold, with a note saying why. A
 * wrong figure reported with confidence is the one outcome that slips past a
 * reviewer, so every rule here prefers declining to guessing.
 */
import { parseMoney } from '@/lib/money';
import { parseLooseDate } from '@/lib/utils';
import { classifyWaiverType, recogniseStatutoryForm } from '@/server/compliance/jurisdictions';
import type {
  BBox,
  ClaimedField,
  ConflictingValue,
  DocType,
  DocumentSegment,
  Extracted,
  ExtractedLine,
  ExtractedPayApp,
  ExtractedWaiver,
  ExtractionConflict,
  ExtractionResult,
  LineAmountField,
  PrintedPageNumber,
  ScheduleGrandTotal,
  Tri,
  WaiverType,
} from '@/server/types';
import { CLAIMED_FIELD_LABEL, CLAIMED_FIELDS, LINE_AMOUNT_FIELDS } from '@/server/types';
import { bboxOf, bboxOfLine, bboxOfRect, imageCoverage, type Cell, type PageText, type PdfText, type Rect, type TextLine } from './pdf-text';

export const TEXT_ENGINE = 'text-layer';

const none = <T>(): Extracted<T> => ({ value: null, confidence: 0, page: null });

/** Below the default review threshold (0.75): shown to a person as "check this". */
const FLAG = 0.6;

// ── Amounts ─────────────────────────────────────────────────────────────────

/**
 * How a run of digits is written.
 *   cents    1,234.56 / 1234.56          US amount with cents
 *   whole    1,234                       US whole dollars with thousands separators
 *   bare     1234                        a plain integer: an amount only where the page prints whole dollars
 *   foreign  1.234,56 / 1 234,56 / 12,50 decimal comma: not read (it would be misread as US)
 *   odd      anything else with digits and separators (1.234, 12.5, 1,23)
 */
export type AmountKind = 'cents' | 'whole' | 'bare' | 'foreign' | 'odd';
export type AmountToken = { raw: string; kind: AmountKind; cents: number | null; index: number };

function kindOf(core: string): AmountKind {
  if (/^\d{1,3}(,\d{3})+\.\d{2}$|^\d+\.\d{2}$/.test(core)) return 'cents';
  if (/^\d{1,3}(,\d{3})+$/.test(core)) return 'whole';
  if (/^\d+$/.test(core)) return 'bare';
  if (/^\d{1,3}(\.\d{3})+(,\d{2})?$|^\d+,\d{2}$/.test(core)) return 'foreign';
  return 'odd';
}

/**
 * Every run of digits that could be an amount, with how it is written, and the
 * sign, parentheses and dollar sign around it. A run glued to letters or other
 * figures (G703, 5a, 10/31/2026, LL-07) is not an amount; a percentage is skipped.
 */
export function scanAmounts(s: string): AmountToken[] {
  const out: AmountToken[] = [];
  const re = /\d[\d,.]*/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(s))) {
    // A full stop or comma closing a sentence is not part of the number.
    const core = m[0].replace(/[.,]+$/, '');
    const start = m.index;
    const end = start + core.length;
    let prefix = /(\(\s?)?(-\s?)?(\$\s?)?(-\s?)?$/.exec(s.slice(Math.max(0, start - 8), start))![0];
    let suffix = /^(\s?\))?(-(?!\d))?/.exec(s.slice(end))![0];
    const opens = prefix.includes('(');
    const closes = suffix.includes(')');
    if (opens && !closes) prefix = prefix.slice(prefix.indexOf('(') + 1).replace(/^\s/, '');
    if (closes && !opens) suffix = suffix.replace(/\s?\)/, '');
    const from = start - prefix.length;
    const to = end + suffix.length;
    const before = s[from - 1] ?? '';
    const after = s.slice(to);
    if (/[A-Za-z0-9_/.,]/.test(before)) continue;
    if (/^[A-Za-z0-9_]/.test(after) || /^[/-]\d/.test(after) || /^\s?%/.test(after)) continue;
    const raw = s.slice(from, to);
    const kind = kindOf(core);
    const cents = kind === 'cents' || kind === 'whole' || kind === 'bare' ? parseMoney(raw) : null;
    out.push({ raw, kind, cents, index: from });
  }
  return out;
}

const isPercent = (s: string) => /^\(?-?\d{1,3}([.,]\d+)?\s?%\)?$/.test(s.trim());

/** How a page writes amounts: whole dollars or with cents, and whether it uses a decimal comma. */
type AmountStyle = { wholeDollars: boolean; foreign: number; cents: number };

function amountStyle(page: PageText): AmountStyle {
  let cents = 0;
  let whole = 0;
  let foreign = 0;
  for (const line of page.lines)
    for (const cell of line.cells)
      for (const t of scanAmounts(cell.text)) {
        if (t.kind === 'cents') cents++;
        else if (t.kind === 'whole') whole++;
        else if (t.kind === 'foreign') foreign++;
      }
  return { wholeDollars: cents === 0 && whole >= 2, foreign, cents };
}

const styleCache = new WeakMap<PageText, AmountStyle>();
const styleOf = (page: PageText): AmountStyle => {
  let s = styleCache.get(page);
  if (!s) styleCache.set(page, (s = amountStyle(page)));
  return s;
};

const readable = (t: AmountToken, style: AmountStyle) => t.cents !== null && (t.kind !== 'bare' || style.wholeDollars);

/**
 * Readable amounts inside a phrase. A plain integer in running text ("Line 1 + 2",
 * "Application No. 4") is never an amount here; it can only be one as a table
 * cell of its own on a page that prints whole dollars (see `cellAmount`).
 */
function moneyTokens(s: string): Array<{ raw: string; cents: number; index: number }> {
  return scanAmounts(s)
    .filter((t) => t.cents !== null && t.kind !== 'bare')
    .map((t) => ({ raw: t.raw, cents: t.cents!, index: t.index }));
}

type CellAmount = { kind: 'money'; cents: number; bare: boolean } | { kind: 'zero' } | { kind: 'unreadable'; raw: string } | { kind: 'percent' } | null;

/** What a table cell holds: an amount, a dash for zero, a figure that cannot be read safely, a percentage, or text (null). */
function cellAmount(cell: Cell, style: AmountStyle): CellAmount {
  const t = cell.text.trim();
  if (!t) return null;
  if (isPercent(t)) return { kind: 'percent' };
  if (/^\$?\s?[-–—]{1,3}\s?$/.test(t)) return { kind: 'zero' };
  const toks = scanAmounts(t);
  const squash = (x: string) => x.replace(/\s+/g, '');
  if (toks.length === 1 && squash(toks[0]!.raw) === squash(t)) {
    const tok = toks[0]!;
    return readable(tok, style) ? { kind: 'money', cents: tok.cents!, bare: tok.kind === 'bare' } : { kind: 'unreadable', raw: t };
  }
  if (/\d/.test(t) && /^[\d$().,\s\-–—]+$/.test(t)) return { kind: 'unreadable', raw: t };
  return null;
}

// ── Page classification ─────────────────────────────────────────────────────

const PAY_APP_SUM = /original (sub)?contract (sum|amount|value|price)/;
const PAY_APP_DUE = /current payment due|(amount|payment) (due|requested) this (application|period|requisition)|current amount due/;
const LETTER = /^\s*dear\b|\bsincerely\b|\b(best |kind )?regards\b|\benclosed (please find|is|are)\b|\bplease find enclosed\b/;
const WAIVER_TITLE = /\b(lien|claim)s? (waiver|release)\b|\bwaiver (and|of) (release|lien|claim)s?\b|\brelease of (lien|claim)s?\b|\bwaiver and release\b/;
const WAIVER_OPERATIVE = /\b(waive[sd]?|release[sd]?)\b[^.]{0,110}\b(liens?|lien rights|claims?|rights to claim)\b/;
const SHEET_CONCEPTS: RegExp[] = [/scheduled|contract value|sov/, /previous|previously|prior/, /this period|current (billing|period)/, /stored/, /to date/, /balance|remaining/, /retainage|retention/];

/** Lines that carry an amount of their own (a summary page's figures). */
function moneyLines(page: PageText, style: AmountStyle): number {
  return page.lines.filter((l) => l.cells.some((c) => cellAmount(c, style)?.kind === 'money')).length;
}

/** Whether a page has a usable text layer. A page that is mostly an image with (almost) no text is a scan. */
function isUnreadable(page: PageText): boolean {
  return (page.chars ?? page.text.replace(/\s/g, '').length) < 20 && imageCoverage(page) >= 0.5;
}

export function classifyPage(page: PageText): { type: DocType; confidence: number } {
  if (isUnreadable(page)) return { type: 'other', confidence: 0 };
  const t = page.text.toLowerCase().replace(/\s+/g, ' ');
  const has = (re: RegExp) => re.test(t);
  // A title is printed at the top; the same words further down ("The Continuation Sheet is attached") are a reference to another page.
  const title = page.lines
    .filter((l) => l.y < page.height * 0.2)
    .map((l) => l.text.toLowerCase())
    .join(' ');
  const style = styleOf(page);
  // A schedule is a table: at least one row with five or more amounts across.
  const table = page.lines.some((l) => l.cells.filter((c) => { const a = cellAmount(c, style); return a?.kind === 'money' && !a.bare; }).length >= 5);
  // Column headings are usually stacked ("SCHEDULED" over "VALUE"), so match the words, not the phrase.
  if (/continuation sheet/.test(title) && has(/scheduled/)) return { type: 'continuation_sheet', confidence: 0.98 };
  const concepts = SHEET_CONCEPTS.filter((re) => has(re)).length;
  if (
    !has(PAY_APP_SUM) &&
    table &&
    ((has(/scheduled/) && has(/balance/) && has(/to finish/) && has(/this period|work completed/)) || (/schedule of values|continuation|billing detail/.test(title) && concepts >= 4) || concepts >= 5)
  )
    return { type: 'continuation_sheet', confidence: 0.88 };
  if (has(/application and certificat(e|ion) for payment/) && has(/original contract (sum|amount)/)) return { type: 'pay_application', confidence: 0.98 };
  if (has(PAY_APP_SUM) && has(PAY_APP_DUE)) return { type: 'pay_application', confidence: 0.9 };
  // Titled as an application for payment, with its own figures, even when the line labels are not the standard ones.
  if (/application (and certificate )?for payment|payment application|pay application|(payment )?requisition( for payment)?/.test(title) && !table && moneyLines(page, style) >= 5)
    return { type: 'pay_application', confidence: 0.85 };

  // A lien waiver releases rights; a letter that mentions one does not.
  const flat = page.text.replace(/\s+/g, ' ');
  if (recogniseStatutoryForm(flat)) return { type: 'lien_waiver', confidence: 0.97 };
  const top = page.lines.filter((l) => l.y < page.height * 0.3).map((l) => l.text.toLowerCase()).join(' ');
  const operative = has(WAIVER_OPERATIVE);
  const letter = has(LETTER);
  if (operative && (WAIVER_TITLE.test(top) || has(/\bwaiver\b|\brelease\b/)) && !letter) return { type: 'lien_waiver', confidence: WAIVER_TITLE.test(top) ? 0.95 : 0.85 };
  if (operative && letter) return { type: 'lien_waiver', confidence: 0.5 };
  if (has(WAIVER_TITLE) && !letter) return { type: 'lien_waiver', confidence: 0.6 };

  if (has(/certificate of (liability )?insurance/)) return { type: 'insurance', confidence: 0.9 };
  if (has(/change order (no|number|#)/) && !has(/original contract sum/)) return { type: 'change_order', confidence: 0.8 };
  if (has(/\binvoice\b/) && has(/invoice (no|number|#|date)/)) return { type: 'invoice', confidence: 0.8 };
  if (has(/subcontract agreement/)) return { type: 'contract', confidence: 0.75 };
  return { type: 'other', confidence: letter ? 0.6 : 0.3 };
}

/** A page that carries a pay application's own amount block (so a second one starts a new application). */
function startsPayApplication(page: PageText): boolean {
  const t = page.text.toLowerCase().replace(/\s+/g, ' ');
  return PAY_APP_SUM.test(t) && PAY_APP_DUE.test(t);
}

function segmentPages(pages: PageText[]): DocumentSegment[] {
  const segments: DocumentSegment[] = [];
  for (const page of pages) {
    const { type, confidence } = classifyPage(page);
    const last = segments[segments.length - 1];
    // Each waiver page stands alone, and each page with its own G702 amount block starts a new application.
    const separate = type === 'lien_waiver' || (type === 'pay_application' && startsPayApplication(page));
    if (last && last.type === type && !separate && last.pageEnd === page.page - 1) {
      last.pageEnd = page.page;
      last.confidence = Math.min(last.confidence, confidence);
    } else {
      segments.push({ type, pageStart: page.page, pageEnd: page.page, confidence });
    }
  }
  return segments;
}

// ── Page numbering ──────────────────────────────────────────────────────────

const PAGE_MARK: RegExp[] = [/\b(?:page|sheet|pg\.?)\s*(\d{1,3})\s*(?:of|\/)\s*(\d{1,3})\b/i, /^\s*(\d{1,3})\s+of\s+(\d{1,3})\s*$/i, /^\s*(?:page|sheet)\s*(\d{1,3})\s*$/i];

/** "Page x of y" printed in the top or bottom margin. Body text that mentions a page is not a page number. */
function printedPageNumber(page: PageText): PrintedPageNumber | null {
  for (const line of page.lines) {
    if (line.y > page.height * 0.12 && line.y < page.height * 0.88) continue;
    for (const cell of line.cells) {
      if (cell.text.length > 40) continue;
      for (const re of PAGE_MARK) {
        const m = re.exec(cell.text);
        if (!m) continue;
        const number = Number(m[1]);
        const of = m[2] !== undefined ? Number(m[2]) : null;
        if (number < 1 || (of !== null && (of < number || of > 500))) continue;
        return { page: page.page, number, of, source: cell.text.trim(), bbox: bboxOf(page, cell) };
      }
    }
  }
  return null;
}

// ── Label → value helpers ───────────────────────────────────────────────────

/**
 * Find the value printed for a label: on the same line to its right, or — when
 * the form stacks labels above values — directly underneath.
 */
function labelledText(page: PageText, labels: RegExp[]): { text: string; cell: Cell } | null {
  for (const label of labels) {
    for (let li = 0; li < page.lines.length; li++) {
      const line = page.lines[li]!;
      for (let ci = 0; ci < line.cells.length; ci++) {
        const cell = line.cells[ci]!;
        const m = label.exec(cell.text);
        if (!m || m.index > 2) continue;
        const rest = cell.text.slice(m.index + m[0].length).replace(/^[\s:#.]+/, '').trim();
        if (rest) return { text: rest, cell };
        const next = line.cells[ci + 1];
        if (next && next.x - (cell.x + cell.w) < 160 && !/:\s*$/.test(next.text)) return { text: next.text.trim(), cell: next };
        for (const below of page.lines.slice(li + 1, li + 3)) {
          const under = below.cells.find((c) => Math.abs(c.x - cell.x) < 6);
          if (under && !/:\s*$/.test(under.text)) return { text: under.text.trim(), cell: under };
        }
      }
    }
  }
  return null;
}

function textField(page: PageText, labels: RegExp[], confidence = 0.92): Extracted<string> {
  const hit = labelledText(page, labels);
  if (!hit || !hit.text) return none();
  return { value: hit.text, confidence, page: page.page, bbox: bboxOf(page, hit.cell), source: hit.text };
}

const DATE = /(\d{1,2}[/\-.]\d{1,2}[/\-.]\d{2,4}|\d{4}-\d{2}-\d{2}|[A-Za-z]{3,9}\.? \d{1,2},? \d{4}|\d{1,2} [A-Za-z]{3,9}\.?,? \d{4})/g;

/**
 * A date printed for a label. When the label is followed by a range ("10/01/2026 – 10/31/2026"),
 * `range: 'end'` takes the last date (a period's end); otherwise a second date makes it ambiguous.
 */
function dateField(page: PageText, labels: RegExp[], range: 'end' | 'reject' = 'reject'): Extracted<string> {
  const hit = labelledText(page, labels);
  if (!hit) return none();
  const found = [...hit.text.matchAll(DATE)].map((m) => m[1]!);
  const pick = found.length === 1 ? found[0] : found.length === 2 && range === 'end' ? found[1] : undefined;
  const iso = parseLooseDate(pick);
  if (!iso) return { value: null, confidence: 0.2, page: page.page, bbox: bboxOf(page, hit.cell), source: hit.text };
  return { value: iso, confidence: found.length === 2 ? 0.9 : 0.95, page: page.page, bbox: bboxOf(page, hit.cell), source: pick! };
}

// ── Pay application (G702) ──────────────────────────────────────────────────

const AMOUNT_LABELS: Record<ClaimedField, { prefix: string; patterns: RegExp[] }> = {
  originalContractSum: { prefix: '1', patterns: [/original (sub)?contract (sum|amount|value|price)/i] },
  netChangeOrders: { prefix: '2', patterns: [/net change by change orders?/i, /net changes? (by|from) change orders?/i, /approved change orders?( \(net\))?( to date)?/i, /net change orders?/i] },
  contractSumToDate: { prefix: '3', patterns: [/contract sum to date/i, /(revised|current|adjusted) (sub)?contract (sum|amount|value)/i] },
  totalCompletedStored: { prefix: '4', patterns: [/total completed (&|and) stored to\s*date/i, /total (work )?completed (&|and) (materials )?stored/i, /^work completed (and stored )?to date/i] },
  retainageWork: { prefix: 'a', patterns: [/%\s*of completed work/i, /retainage on completed work/i, /^on work completed/i] },
  retainageStored: { prefix: 'b', patterns: [/%\s*of stored materials?/i, /retainage on stored materials?/i, /^on stored materials?/i] },
  retainageTotal: { prefix: '5', patterns: [/total retainage/i, /retainage (withheld|held) to date/i, /^less retention\b/i] },
  totalEarnedLessRetainage: { prefix: '6', patterns: [/total earned (to date )?less retainage/i, /^net earned to date/i] },
  lessPreviousCertificates: { prefix: '7', patterns: [/less previous (certificates|applications|payments|billings)/i, /previous certificates for payment/i, /^less prior payments/i] },
  currentPaymentDue: { prefix: '8', patterns: [/current payment due/i, /amount due this (application|period)/i, /current amount due/i, /^payment requested this (period|application)/i] },
  balanceToFinish: { prefix: '9', patterns: [/balance to (finish|complete)/i, /^remaining balance\b/i] },
};

const ALL_AMOUNT_PATTERNS = Object.values(AMOUNT_LABELS).flatMap((d) => d.patterns);

function amountOnLine(line: TextLine, pattern: RegExp, style: AmountStyle): { cents: number; cell: Cell; raw: string } | null {
  // Walk the cells; once the label has been seen, the right-most amount on the line is the value.
  let seen = false;
  let best: { cents: number; cell: Cell; raw: string } | null = null;
  for (const cell of line.cells) {
    if (!seen) {
      const m = pattern.exec(cell.text);
      if (!m) continue;
      seen = true;
      for (const tok of moneyTokens(cell.text.slice(m.index + m[0].length))) best = { cents: tok.cents, cell, raw: tok.raw };
      continue;
    }
    const whole = cellAmount(cell, style);
    if (whole?.kind === 'money') best = { cents: whole.cents, cell, raw: cell.text };
    else for (const tok of moneyTokens(cell.text)) best = { cents: tok.cents, cell, raw: tok.raw };
  }
  return best;
}

/** Whether the label line carries a figure that cannot be read safely (a decimal comma, a stray format). */
function unreadableOnLine(line: TextLine, pattern: RegExp): string | null {
  let seen = false;
  for (const cell of line.cells) {
    let from = 0;
    if (!seen) {
      const m = pattern.exec(cell.text);
      if (!m) continue;
      seen = true;
      from = m.index + m[0].length;
    }
    const odd = scanAmounts(cell.text.slice(from)).find((t) => t.kind === 'foreign' || t.kind === 'odd');
    if (odd) return odd.raw;
  }
  return null;
}

function amountField(page: PageText, field: ClaimedField, notes: string[]): Extracted<number> {
  const def = AMOUNT_LABELS[field];
  const style = styleOf(page);
  type Hit = { cents: number; cell: Cell; raw: string; numbered: boolean };
  const hits: Hit[] = [];
  for (const pattern of def.patterns) {
    for (let i = 0; i < page.lines.length; i++) {
      const line = page.lines[i]!;
      if (!line.cells.some((c) => pattern.test(c.text))) continue;
      const first = line.cells[0]?.text.trim() ?? '';
      const numbered = new RegExp(`^${def.prefix}[.)]?(\\s|$)`, 'i').test(first);
      const odd = unreadableOnLine(line, pattern);
      if (odd) {
        notes.push(`“${CLAIMED_FIELD_LABEL[field]}” on page ${page.page} is printed as “${odd}”, which is not a US-format amount (it may use a decimal comma). It was not read; enter it by hand.`);
        return { value: null, confidence: 0, page: page.page, source: odd };
      }
      let found = amountOnLine(line, pattern, style);
      const below = page.lines[i + 1];
      if (!found && below) {
        const cells = below.cells.filter((c) => c.text.trim() !== '$');
        const amounts = cells.filter((c) => cellAmount(c, style)?.kind === 'money');
        const h = median(line.cells.map((c) => c.h)) || 8;
        // Another field's line starts with its own number ("4.", "b.") or label.
        const ownField = /^(\d{1,2}|[a-z])[.)](\s|$)/i.test(cells[0]?.text ?? '') || ALL_AMOUNT_PATTERNS.some((p) => cells.some((c) => p.test(c.text)));
        if (cells.length > 0 && amounts.length === cells.length) {
          // Value printed on the line below the label.
          const c = cells[cells.length - 1]!;
          found = { cents: (cellAmount(c, style) as { cents: number }).cents, cell: c, raw: c.text };
        } else if (!ownField && below.y - line.y <= h * 1.5 && amounts.length === 1 && cells.every((c) => c === amounts[0] || c.x + c.w < amounts[0]!.x)) {
          // The label wraps onto a second line ("(Line 1 + 2)") and the amount is printed on that line.
          const c = amounts[0]!;
          found = { cents: (cellAmount(c, style) as { cents: number }).cents, cell: c, raw: c.text };
        }
      }
      if (found) hits.push({ ...found, numbered });
    }
    if (hits.length > 0) break;
  }
  if (hits.length === 0) return none();
  const chosen = hits.find((h) => h.numbered) ?? hits[0]!;
  const conflicting = hits.some((h) => h.cents !== chosen.cents);
  if (conflicting && !chosen.numbered) notes.push(`More than one amount on page ${page.page} could be “${CLAIMED_FIELD_LABEL[field]}”; the first was used.`);
  return {
    value: chosen.cents,
    confidence: chosen.numbered ? 0.98 : conflicting ? FLAG : 0.92,
    page: page.page,
    bbox: bboxOf(page, chosen.cell),
    source: chosen.raw.trim(),
  };
}

const ESIGN = [
  /electronically signed by:?\s+([A-Z][A-Za-z.'’ -]+?)(?:,| on |\s{2,}|$)/i,
  /docusigned by:?\s+([A-Z][A-Za-z.'’ -]+?)(?:,|\s{2,}|$)/i,
  /digitally signed by:?\s+([A-Z][A-Za-z.'’ -]+?)(?:,|\s{2,}|$)/i,
  /\/s\/\s*([A-Z][A-Za-z.'’ -]+?)(?:,|\s{2,}|$)/,
];

function signature(page: PageText, notes: string[], what: string): { signed: Extracted<Tri>; signerName: Extracted<string> } {
  for (const line of page.lines) {
    for (const cell of line.cells) {
      for (const re of ESIGN) {
        const m = re.exec(cell.text);
        if (m) {
          const bbox = bboxOf(page, cell);
          return {
            signed: { value: 'yes', confidence: 0.9, page: page.page, bbox, source: cell.text },
            signerName: { value: m[1]!.trim(), confidence: 0.9, page: page.page, bbox, source: m[1]!.trim() },
          };
        }
      }
    }
  }
  notes.push(`No electronic signature marker was found on the ${what}. A handwritten or stamped signature cannot be detected from the text layer, so it needs a visual check.`);
  return { signed: { value: 'unclear', confidence: 0.4, page: page.page }, signerName: none() };
}

function notarization(page: PageText): Extracted<Tri> {
  const idx = page.lines.findIndex((l) => /subscribed and sworn/i.test(l.text));
  if (idx < 0) return { value: 'no', confidence: 0.7, page: page.page, source: 'No notary acknowledgement block on the page.' };
  const block = page.lines.slice(idx, idx + 6);
  const blockText = block.map((l) => l.text).join(' ');
  const blanks = /_{4,}/.test(blockText);
  const notaryLine = page.lines.find((l) => /notary public/i.test(l.text));
  const named =
    !!notaryLine &&
    (notaryLine.cells.some((c) => !/notary public/i.test(c.text) && /[A-Za-z]{3,}/.test(c.text)) ||
      // the name is often printed just above the signature rule
      page.lines.some((l) => Math.abs(l.y - notaryLine.y) < 22 && l !== notaryLine && l.cells.some((c) => c.x > notaryLine.cells[0]!.x + 40 && /^[A-Z][A-Za-z.' -]{4,}$/.test(c.text))));
  const bbox = bboxOfLine(page, block[0]!);
  if (!blanks && named) return { value: 'yes', confidence: 0.8, page: page.page, bbox, source: block[0]!.text };
  return { value: 'unclear', confidence: 0.5, page: page.page, bbox, source: block[0]!.text };
}

const APP_NO_LABELS = [/^application\s*(no|number|#)\.?:?/i, /^(pay(ment)?\s*)?app(lication)?\s*(no|number|#)\.?:?/i, /^requisition\s*(no|number|#)\.?:?/i];

function applicationNumberOn(page: PageText): Extracted<number> {
  const hit = labelledText(page, APP_NO_LABELS);
  const m = hit ? /^\s*#?\s*(\d{1,4})\b/.exec(hit.text) : null;
  return m ? { value: Number(m[1]), confidence: 0.97, page: page.page, bbox: bboxOf(page, hit!.cell), source: hit!.text } : none();
}

function parsePayApplication(page: PageText, notes: string[]): ExtractedPayApp {
  const amounts = {} as Record<ClaimedField, Extracted<number>>;
  for (const field of CLAIMED_FIELDS) amounts[field] = amountField(page, field, notes);
  const sig = signature(page, notes, 'pay application');

  return {
    applicationNumber: applicationNumberOn(page),
    periodTo: dateField(page, [/^period\s*to:?/i, /^(for\s*)?period\s*ending:?/i, /^billing\s*period\s*(to|ending)?:?/i, /^period:/i], 'end'),
    applicationDate: dateField(page, [/^application\s*date:?/i, /^date\s*of\s*application:?/i]),
    projectName: textField(page, [/^project(\s*name)?:/i, /^job(\s*name)?:/i]),
    projectNumber: textField(page, [/^project\s*(no|number|#)\.?:?/i, /^job\s*(no|number|#)\.?:?/i]),
    contractorName: textField(page, [/^from\s*(\(?sub\)?)?\s*contractor\)?:?/i, /^from:/i, /^(sub)?contractor:/i]),
    toName: textField(page, [/^to\s*\(?(owner|contractor|general contractor|gc)\)?:?/i, /^to:/i, /^bill to:?/i]),
    contractNumber: textField(page, [/^(sub)?contract\s*(no|number|#)\.?:?/i]),
    contractDate: dateField(page, [/^(sub)?contract\s*date:?/i]),
    amounts,
    signed: sig.signed,
    signerName: sig.signerName,
    notarized: notarization(page),
  };
}

// ── Continuation sheet (G703) ───────────────────────────────────────────────

const LETTER_FIELD: Record<string, LineAmountField> = {
  C: 'scheduledValue',
  D: 'previous',
  E: 'thisPeriod',
  F: 'stored',
  G: 'total',
  H: 'balance',
  I: 'retainage',
};
const ITEM_NO = /^[A-Za-z]{0,3}[-.]?\d{1,4}[A-Za-z]?([.-]\d{1,3})*$/;

/**
 * Column headings → field. Order matters: the first rule that matches wins, so
 * the more specific concepts come first ("total completed and stored to date"
 * mentions storage but is the total; "previously billed to date" is previous).
 * `ignore` marks money columns that are not one of ours (original value,
 * change orders); they are read past, never guessed into another field.
 */
const HEAD_RULES: Array<[RegExp, LineAmountField | 'ignore']> = [
  [/retain|retention|holdback/, 'retainage'],
  [/balance|remaining|to finish|left to (bill|complete)/, 'balance'],
  [/previous|prior|previously/, 'previous'],
  [/this (period|application|requisition|month|billing|estimate)|current (billing|period|application|request|requisition|month)|period billing/, 'thisPeriod'],
  [/(total|completed|billed)\b.*\bto date|to date\b.*\b(total|completed)|completed (and|&) stored/, 'total'],
  [/stored|materials? on (hand|site)/, 'stored'],
  [/original|change orders?|changes|adjustments?/, 'ignore'],
  [/revised|scheduled|contract (value|amount|sum)|sov|budget|value/, 'scheduledValue'],
];

/** Rows that repeat other rows' figures (subtotals, amounts carried between pages): never line items, never the grand total. */
const FORWARD_ROW = /\b(sub-?\s?totals?|page totals?|totals? (this|for this) page|brought forward|carried forward|balance (brought|carried) forward|forwarded|b\/f|c\/f)\b|^continued\b|\bcontinued (on|from) (the )?(next|previous|prior) page\b/i;
/** The grand-total row: the label is the word "total" and little else, so a line item like "Total station survey" is not taken for it. */
const TOTAL_ROW = /^(?:(?:schedule|contract|sov|project|job)\s+)?(?:grand\s+)?totals?\s*:?$|\bgrand\s+totals?\b|^totals?\s+(?:to date|this (?:application|period))\s*:?$/i;

type Column = { right: number; left: number; field: LineAmountField | null; heading: string; letter: string | null };
type SheetLayout = { columns: Column[]; confidence: number; how: string };
type SheetRow = { lines: TextLine[]; values: Partial<Record<LineAmountField, number>>; unreadable: number; stray: number; label: Cell[]; kind: 'line' | 'total' | 'forward' };
type SheetPage = {
  lines: ExtractedLine[];
  total: { values: Partial<Record<LineAmountField, number | null>>; label: string; bbox: BBox; confidence: number } | null;
  layout: SheetLayout | null;
};

const median = (xs: number[]) => {
  const s = [...xs].sort((a, b) => a - b);
  return s.length ? s[Math.floor(s.length / 2)]! : 0;
};

function headingField(text: string): LineAmountField | 'ignore' | null {
  const t = text.toLowerCase().replace(/\s+/g, ' ');
  for (const [re, field] of HEAD_RULES) if (re.test(t)) return field;
  return null;
}

function parseContinuationPage(page: PageText, notes: string[], previous: SheetLayout | null): SheetPage {
  const style = styleOf(page);
  const annotated = page.lines.map((line) => ({ line, cells: line.cells.map((cell) => ({ cell, amt: cellAmount(cell, style) })) }));
  const strong = annotated.filter((l) => l.cells.filter((c) => c.amt?.kind === 'money' && !c.amt.bare).length >= 3);
  if (strong.length === 0) {
    if (style.foreign > 0) notes.push(`The schedule on page ${page.page} prints amounts with a decimal comma (for example 1.234,56). They were not read, so a US-format reading cannot mistake them; key the lines by hand.`);
    return { lines: [], total: null, layout: null };
  }

  // Numeric columns are right-aligned: cluster the right edges of the amounts.
  const edges = strong.flatMap((l) => l.cells.filter((c) => c.amt?.kind === 'money' && !c.amt.bare).map((c) => c.cell.x + c.cell.w)).sort((a, b) => a - b);
  const rights: number[] = [];
  for (const e of edges) {
    if (rights.length === 0 || e - rights[rights.length - 1]! > 8) rights.push(e);
    else rights[rights.length - 1] = Math.max(rights[rights.length - 1]!, e);
  }
  const width = rights.length > 1 ? median(rights.slice(1).map((r, i) => r - rights[i]!)) : 60;
  const columns: Column[] = rights.map((right, i) => ({ right, left: i === 0 ? right - width * 1.5 : rights[i - 1]! + 1, field: null, heading: '', letter: null }));
  const firstMoneyLeft = Math.min(...strong.flatMap((l) => l.cells.filter((c) => c.amt?.kind === 'money' && !c.amt.bare && c.cell.x + c.cell.w <= rights[0]! + 8).map((c) => c.cell.x)));
  const firstRowY = Math.min(...strong.map((l) => l.line.y));

  // The heading band: the lines stacked just above the first row.
  const above = page.lines.filter((l) => l.y < firstRowY).sort((a, b) => b.y - a.y);
  const header: TextLine[] = [];
  let lastY = firstRowY;
  for (const line of above) {
    const h = median(line.cells.map((c) => c.h)) || 7;
    const gap = lastY - line.y;
    if (gap > (header.length === 0 ? 34 : Math.max(10, h * 1.9))) break;
    if (line.cells.some((c) => cellAmount(c, style)?.kind === 'money')) break;
    header.push(line);
    lastY = line.y;
  }
  header.reverse();
  // Headings of narrow columns run into each other on a line; place each run of text the PDF drew on its own.
  const runs = (l: TextLine) => l.cells.flatMap((c) => c.parts ?? [c]);
  const isLetter = (c: Cell) => /^[A-J]$/.test(c.text.trim());
  const letterLine = header.find((l) => runs(l).filter(isLetter).length >= 5) ?? null;
  for (const col of columns) {
    const w = col.right - col.left;
    const words: string[] = [];
    for (const line of header) {
      if (line === letterLine) continue;
      for (const c of runs(line)) {
        const overlap = Math.min(c.x + c.w, col.right + 2) - Math.max(c.x, col.left);
        if (overlap >= 0.5 * Math.min(c.w, w)) words.push(c.text);
      }
    }
    col.heading = words.join(' ').trim();
    const letter = letterLine ? runs(letterLine).find((c) => isLetter(c) && c.x + c.w / 2 >= col.left && c.x + c.w / 2 <= col.right + 3) : undefined;
    col.letter = letter ? letter.text.trim() : null;
  }

  // ── Which column is which ──
  const fromHeading = columns.map((c) => headingField(c.heading));
  const fromLetter = columns.map((c) => (c.letter ? (LETTER_FIELD[c.letter] ?? null) : null));
  const recognised = fromHeading.filter((f) => f && f !== 'ignore').length;
  const lettered = fromLetter.filter(Boolean).length;
  let layout: SheetLayout | null = null;
  const fail = (why: string): SheetPage => {
    notes.push(`The schedule of values on page ${page.page}: ${why} Its lines were not read; key them by hand.`);
    return { lines: [], total: null, layout: null };
  };
  if (recognised >= 3) {
    const disagree = columns.some((_, i) => fromHeading[i] && fromHeading[i] !== 'ignore' && fromLetter[i] && fromHeading[i] !== fromLetter[i]);
    const agree = lettered >= 3 && !disagree;
    columns.forEach((c, i) => (c.field = fromHeading[i] === 'ignore' ? null : (fromHeading[i] ?? (agree ? fromLetter[i] : null))));
    if (disagree) {
      notes.push(`On page ${page.page} the column letters do not match the column headings, so the columns were read by their headings. Check the schedule against the document.`);
      layout = { columns, confidence: FLAG, how: 'headings (letters disagree)' };
    } else layout = { columns, confidence: agree ? 0.97 : 0.93, how: agree ? 'headings and letters' : 'headings' };
  } else if (lettered >= 4) {
    columns.forEach((c, i) => (c.field = fromLetter[i]));
    layout = { columns, confidence: 0.9, how: 'column letters' };
  } else if (previous && previous.columns.length === columns.length && previous.columns.every((p, i) => Math.abs(p.right - columns[i]!.right) <= 6)) {
    columns.forEach((c, i) => (c.field = previous.columns[i]!.field));
    layout = { columns, confidence: previous.confidence, how: previous.how };
  } else if (columns.length === 7 || columns.length === 6) {
    const order: LineAmountField[] = ['scheduledValue', 'previous', 'thisPeriod', 'stored', 'total', 'balance', 'retainage'];
    columns.forEach((c, i) => (c.field = order[i] ?? null));
    notes.push(`The schedule on page ${page.page} has no column headings or letters that could be recognised; its ${columns.length} amount columns were assumed to be in the standard G703 order. Check every column.`);
    layout = { columns, confidence: 0.7, how: 'position' };
  } else {
    return fail(`its ${columns.length} amount columns have no headings or letters that could be recognised, so they could not be identified.`);
  }

  // A field claimed by two columns cannot be told apart: read neither.
  for (const f of LINE_AMOUNT_FIELDS) {
    const owners = columns.filter((c) => c.field === f);
    if (owners.length > 1) {
      for (const c of owners) c.field = null;
      notes.push(`On page ${page.page} two columns both look like “${f}”; neither was read.`);
    }
  }
  if (!columns.some((c) => c.field === 'thisPeriod' || c.field === 'total')) return fail('neither the work-this-period nor the total-to-date column could be identified.');

  const columnOf = (cell: Cell, amt: CellAmount): Column | null => {
    const right = cell.x + cell.w;
    if (amt?.kind === 'money' || amt?.kind === 'unreadable') {
      let best: Column | null = null;
      let dist = Infinity;
      for (const c of columns) {
        const d = Math.abs(c.right - right);
        if (d < dist) [best, dist] = [c, d];
      }
      return dist <= 10 ? best : null;
    }
    // A dash need not sit flush right; it belongs to the column it is drawn in.
    const mid = cell.x + cell.w / 2;
    return columns.find((c) => mid >= c.left && mid <= c.right + 3) ?? null;
  };

  // ── Rows ──
  const rows: SheetRow[] = [];
  const textOnly: Array<{ line: TextLine; label: Cell[] }> = [];
  for (const { line, cells } of annotated) {
    if (line.y < firstRowY - 1) continue;
    const values: SheetRow['values'] = {};
    const label: Cell[] = [];
    let amounts = 0;
    let unreadable = 0;
    let stray = 0;
    for (const { cell, amt } of cells) {
      // Everything left of the first amount column is the item number and description, whatever it looks like.
      if (cell.x + cell.w <= firstMoneyLeft + 2) {
        label.push(cell);
        continue;
      }
      if (amt === null || amt.kind === 'percent') {
        if (amt === null && cell.x < firstMoneyLeft) label.push(cell);
        else if (amt === null) stray++;
        continue;
      }
      const col = columnOf(cell, amt);
      if (!col) {
        if (amt.kind === 'money') stray++;
        continue;
      }
      amounts++;
      if (amt.kind === 'unreadable') {
        unreadable++;
        continue;
      }
      if (!col.field) continue;
      if (values[col.field] === undefined) values[col.field] = amt.kind === 'money' ? amt.cents : 0;
    }
    if (amounts === 0) {
      if (label.length > 0) textOnly.push({ line, label });
      continue;
    }
    const labelText = label.map((c) => c.text).join(' ').trim();
    const leadsWithItem = !!label[0] && ITEM_NO.test(label[0].text.trim()) && label.length > 1;
    const kind: SheetRow['kind'] = FORWARD_ROW.test(labelText) ? 'forward' : TOTAL_ROW.test(labelText) && !leadsWithItem ? 'total' : 'line';
    if (kind === 'line' && amounts < 2) continue;
    rows.push({ lines: [line], values, unreadable, stray, label, kind });
  }
  if (rows.some((r) => r.unreadable > 0)) notes.push(`Some amounts on the schedule on page ${page.page} are written in a format that cannot be read safely; those cells were left blank.`);

  // Wrapped descriptions: a line of text in the description column set tight under (or over) a row belongs to it.
  const lineH = median(rows.map((r) => median(r.lines[0]!.cells.map((c) => c.h)))) || 7;
  let ambiguous = 0;
  for (const t of textOnly) {
    if (t.label.some((c) => c.x + c.w > firstMoneyLeft + 2)) continue;
    const top = t.line.y;
    const bottom = t.line.y + median(t.label.map((c) => c.h));
    const before = rows.filter((r) => r.lines[r.lines.length - 1]!.y < top).pop();
    const after = rows.find((r) => r.lines[0]!.y > top);
    const gapBefore = before ? top - (before.lines[before.lines.length - 1]!.y + lineH) : Infinity;
    const gapAfter = after ? after.lines[0]!.y - bottom : Infinity;
    const tight = lineH * 0.6;
    const nearBefore = gapBefore <= tight && before?.kind === 'line';
    const nearAfter = gapAfter <= tight && after?.kind === 'line';
    if (nearBefore && nearAfter && Math.abs(gapBefore - gapAfter) < lineH * 0.25) {
      ambiguous++;
      for (const r of [before!, after!]) r.unreadable++;
      continue;
    }
    if (nearBefore && gapBefore <= gapAfter) {
      before!.lines.push(t.line);
      before!.label.push(...t.label);
    } else if (nearAfter) {
      after!.lines.unshift(t.line);
      after!.label.unshift(...t.label);
    }
  }
  if (ambiguous > 0) notes.push(`On page ${page.page}, ${ambiguous} line${ambiguous === 1 ? '' : 's'} of description text could belong to the row above or below; those rows are marked for checking.`);

  // Does the arithmetic of the rows support the column assignment?
  let checkable = 0;
  let inconsistent = 0;
  const rowOk = (v: SheetRow['values']): boolean | null => {
    let ok: boolean | null = null;
    if (v.total !== undefined && v.previous !== undefined && v.thisPeriod !== undefined && v.stored !== undefined) ok = v.total === v.previous + v.thisPeriod + v.stored;
    if (v.balance !== undefined && v.scheduledValue !== undefined && v.total !== undefined) ok = (ok ?? true) && v.balance === v.scheduledValue - v.total;
    return ok;
  };
  for (const r of rows) {
    if (r.kind !== 'line') continue;
    const ok = rowOk(r.values);
    if (ok === null) continue;
    checkable++;
    if (!ok) inconsistent++;
  }
  let confidence = layout.confidence;
  if (checkable >= 2 && inconsistent * 2 > checkable) {
    confidence = Math.min(confidence, FLAG);
    notes.push(`On page ${page.page}, ${inconsistent} of ${checkable} schedule rows do not add up across (G = D + E + F, H = C − G) as the columns were read, so the columns may be misidentified. Check them against the document.`);
  }

  const lines: ExtractedLine[] = [];
  let total: SheetPage['total'] = null;
  for (const r of rows) {
    if (r.kind === 'forward') continue;
    const bbox = bboxOfRows(page, r.lines);
    if (r.kind === 'total') {
      const values: Partial<Record<LineAmountField, number | null>> = {};
      for (const c of columns) if (c.field) values[c.field] = r.values[c.field] ?? null;
      total = { values, label: r.label.map((c) => c.text).join(' ').trim(), bbox, confidence };
      continue;
    }
    const first = r.label[0];
    const hasItemNo = !!first && ITEM_NO.test(first.text.trim()) && r.label.length > 1;
    const itemNo = hasItemNo ? first!.text.trim() : null;
    const description = (hasItemNo ? r.label.slice(1) : r.label).map((c) => c.text).join(' ').replace(/\s+/g, ' ').trim() || null;
    let conf = confidence;
    if (r.unreadable > 0 || r.stray > 0) conf = Math.min(conf, FLAG);
    if (rowOk(r.values) === false) conf = Math.min(conf, 0.7);
    lines.push({
      itemNo,
      description,
      page: page.page,
      bbox,
      confidence: conf,
      scheduledValue: r.values.scheduledValue ?? null,
      previous: r.values.previous ?? null,
      thisPeriod: r.values.thisPeriod ?? null,
      stored: r.values.stored ?? null,
      total: r.values.total ?? null,
      balance: r.values.balance ?? null,
      retainage: r.values.retainage ?? null,
    });
  }
  return { lines, total, layout };
}

function bboxOfRows(page: PageText, lines: TextLine[]): BBox {
  const cells = lines.flatMap((l) => l.cells);
  const x1 = Math.min(...cells.map((c) => c.x));
  const x2 = Math.max(...cells.map((c) => c.x + c.w));
  const y1 = Math.min(...cells.map((c) => c.y));
  const y2 = Math.max(...cells.map((c) => c.y + c.h));
  return bboxOfRect(page, { x: x1 - 2, y: y1 - 2, w: x2 - x1 + 4, h: y2 - y1 + 4 });
}

// ── Lien waiver ─────────────────────────────────────────────────────────────

const SIGNATURE_BLOCK = /^(dated|date( of signature)?|signed|signature|by|name|title|print(ed)? name|sworn|notary)\b/i;

/** A heading "Exceptions:" followed by a list. Returns the items joined, "None" when it says so, or null when there is no such section. */
function exceptionsSection(page: PageText): { text: string | null; found: boolean; cell?: Cell } {
  const idx = page.lines.findIndex((l) => /^\s*(additional\s+)?exceptions?\b/i.test(l.cells[0]?.text ?? ''));
  if (idx < 0) return { text: null, found: false };
  const head = page.lines[idx]!;
  const inline = head.text.replace(/^\s*(additional\s+)?exceptions?\b/i, '').replace(/\([^)]*\)/g, '').replace(/^[\s:.-]+/, '').trim();
  if (inline) return { text: inline, found: true, cell: head.cells[0] };
  const items: string[] = [];
  const h = median(head.cells.map((c) => c.h)) || 9;
  let lastY = head.y;
  for (const line of page.lines.slice(idx + 1)) {
    if (line.y - lastY > h * 2.6) break;
    if (SIGNATURE_BLOCK.test(line.cells[0]?.text ?? '')) break;
    const text = line.text.replace(/^\s*(\d{1,2}[.)]|[a-z][.)]|[-•])\s*/, '').trim();
    if (text) items.push(text);
    lastY = line.y;
  }
  return { text: items.length ? items.join('; ') : null, found: true, cell: head.cells[0] };
}

function parseWaiver(page: PageText, notes: string[]): ExtractedWaiver {
  const flat = page.text.replace(/\s+/g, ' ');
  const style = styleOf(page);
  const form = recogniseStatutoryForm(flat);
  const type: WaiverType = form?.type ?? classifyWaiverType(flat);
  const titleLine = page.lines.find((l) => /waiver|release/i.test(l.text));
  const here = <T>(value: T | null, confidence: number, source?: string | null, cell?: Cell): Extracted<T> =>
    value === null ? none() : { value, confidence, page: page.page, bbox: cell ? bboxOf(page, cell) : null, source: source ?? String(value) };
  const cellWith = (needle: string): Cell | undefined => {
    for (const line of page.lines) for (const cell of line.cells) if (cell.text.includes(needle)) return cell;
    return undefined;
  };
  const grab = (re: RegExp): string | null => re.exec(flat)?.[1]?.trim() ?? null;

  let amountRaw: string | null = null;
  let claimant: Extracted<string> = none();
  let customer: Extracted<string> = none();
  let owner: Extracted<string> = none();
  let job: Extracted<string> = none();
  let through: Extracted<string> = none();

  const money = String.raw`(\(?-?\$?\s?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d{2})?\)?)(?![\d.,]*\d)`;
  if (form?.state === 'CA') {
    claimant = textField(page, [/^name of claimant:?/i]);
    customer = textField(page, [/^name of customer:?/i]);
    job = textField(page, [/^job location:?/i]);
    owner = textField(page, [/^owner:?/i]);
    through = dateField(page, [/^through date:?/i]);
    amountRaw = grab(new RegExp(`amount of check:?\\s*\\$?\\s*${money}`, 'i')) ?? grab(new RegExp(`following (?:progress |final )?payment:?\\s*\\$?\\s*${money}`, 'i'));
  } else if (form?.state === 'TX') {
    amountRaw = grab(new RegExp(`in the sum of\\s*${money}`, 'i'));
    const payee = grab(/payable to (.+?) \(payee/i);
    const company = page.lines.find((l) => /\(company name\)/i.test(l.text))?.cells.find((c) => !/\(company name\)/i.test(c.text));
    claimant = company ? here(company.text.trim(), 0.92, company.text, company) : here(payee, 0.85);
    customer = here(grab(/check from (.+?) \(maker of check\)/i) ?? grab(/or to (.+?) \(person with whom signer contracted\)/i), 0.88);
    owner = here(grab(/property of (.+?) \(owner\)/i), 0.88);
    job = here(grab(/located at (.+?) \(location\)/i), 0.85);
  } else if (form?.state === 'FL') {
    amountRaw = grab(new RegExp(`(?:sum|amount) of\\s*${money}`, 'i'));
    const t = /furnished through (.+?) to (.+?) on the job of (.+?) to the following property/i.exec(flat);
    if (t) {
      const iso = parseLooseDate(t[1]!.trim());
      through = iso ? here(iso, 0.92, t[1]!.trim()) : { value: null, confidence: 0.2, page: page.page, source: t[1] };
      customer = here(t[2]!.trim(), 0.88);
      owner = here(t[3]!.trim(), 0.88);
    } else {
      const f = /furnished to (.+?) on the job of (.+?) to the following property/i.exec(flat);
      if (f) {
        customer = here(f[1]!.trim(), 0.88);
        owner = here(f[2]!.trim(), 0.88);
      }
    }
    const lienor = page.lines.find((l) => /\(lienor\)/i.test(l.text))?.cells.find((c) => !/\(lienor\)/i.test(c.text));
    if (lienor) claimant = here(lienor.text.trim(), 0.92, lienor.text, lienor);
  } else {
    claimant = textField(page, [/^(sub)?contractor:/i, /^claimant:?/i, /^name of claimant:?/i, /^company:?/i], 0.8);
    if (!claimant.value) {
      // "The undersigned, Acme Electric, LLC (“Subcontractor”), …"
      const named = grab(/\bthe undersigned,\s+(.+?),?\s+\((?:the\s+)?["“”']?(?:sub-?contractor|claimant|lienor|contractor|releasor|undersigned)["“”']?\)/i);
      if (named) claimant = here(named, 0.85, named, cellWith(named.slice(0, 20)));
    }
    customer = textField(page, [/^general contractor:?/i, /^(general )?contractor:/i, /^customer:?/i], 0.7);
    owner = textField(page, [/^owner:?/i], 0.8);
    job = textField(page, [/^project:?/i, /^job( location| name)?:?/i], 0.8);
    through = dateField(page, [/^through( date)?:?/i, /^period (ending|through):?/i]);
    if (!through.value) {
      const d = grab(/\b(?:furnished|performed|supplied|provided)\s+(?:through|thru|to and including)\s+([A-Za-z]{3,9}\.? \d{1,2},? \d{4}|\d{1,2}\/\d{1,2}\/\d{2,4})/i);
      const iso = parseLooseDate(d ?? undefined);
      if (iso) through = here(iso, 0.85, d);
    }
    amountRaw = labelledText(page, [/^(payment )?amount(\s*:|\s*$)/i])?.text ?? null;
    if (!amountRaw) {
      // The first figure after "sum of" / "amount of", where it is written in figures at all.
      const m = /(?:sum|amount) of\b(.{0,160})/i.exec(flat);
      const tok = m ? moneyTokens(m[1]!)[0] : undefined;
      // "One Thousand … Dollars ($1,000.00)": the parentheses restate the words in figures; they are not a negative.
      const restated = tok && /^\(.*\)$/.test(tok.raw.trim()) && /\b(dollars|\d{2}\/100)\s*$/i.test(m![1]!.slice(0, tok.index));
      amountRaw = tok ? (restated ? tok.raw.trim().slice(1, -1) : tok.raw) : null;
      if (m && !tok && /\bdollars\b/i.test(m[1]!)) notes.push(`The amount on the lien waiver on page ${page.page} is written only in words; it was not read. Enter it by hand.`);
    }
    if (customer.value && claimant.value && customer.value === claimant.value) customer = none();
  }

  let amountTok = amountRaw ? moneyTokens(amountRaw)[0] : undefined;
  if (amountTok && amountTok.cents < 0) {
    // A waiver releases a payment; it cannot be for a negative amount. Something was misread.
    notes.push(`The lien waiver on page ${page.page} appears to state a negative amount (${amountTok.raw.trim()}); it was not read. Enter it by hand.`);
    amountTok = undefined;
  } else if (!amountTok) notes.push(`No amount could be read from the lien waiver on page ${page.page}.`);
  const amountCell = amountTok ? cellWith(amountTok.raw.trim().replace(/^\(|\)$/g, '')) : undefined;

  let exceptions: Extracted<string> = none();
  const section = form ? null : exceptionsSection(page);
  if (section?.found) {
    exceptions = section.text
      ? { value: section.text, confidence: 0.8, page: page.page, bbox: section.cell ? bboxOf(page, section.cell) : null, source: section.text }
      : { value: null, confidence: 0.6, page: page.page, source: 'Exceptions section left blank.' };
  } else {
    const grabbed = grab(/(?:additional )?exceptions?:\s*(.+?)(?:\s{2,}|signature|date of signature|dated on|$)/i);
    if (grabbed) exceptions = { value: grabbed, confidence: 0.8, page: page.page, source: grabbed };
  }
  const sig = signature(page, notes, 'lien waiver');
  const title = textField(page, [/^(title|claimant.?s title):?/i], 0.85);
  const signedDate = dateField(page, [/^date of signature:?/i, /^date:?/i, /^dated( on)?:?/i]);

  return {
    page: page.page,
    waiverType: { value: type, confidence: form ? 0.96 : type === 'unknown' ? 0.3 : 0.7, page: page.page, bbox: titleLine ? bboxOfLine(page, titleLine) : null, source: titleLine?.text ?? null },
    formState: form ? { value: form.state, confidence: 0.95, page: page.page, source: form.title } : none(),
    title: titleLine ? { value: titleLine.text.trim(), confidence: 0.95, page: page.page, bbox: bboxOfLine(page, titleLine), source: titleLine.text } : none(),
    claimant,
    customer,
    owner,
    jobDescription: job,
    throughDate: through,
    amount: amountTok ? { value: amountTok.cents, confidence: form ? 0.95 : 0.85, page: page.page, bbox: amountCell ? bboxOf(page, amountCell) : null, source: amountTok.raw.trim() } : none(),
    exceptions,
    signed: sig.signed,
    signerName: sig.signerName,
    signerTitle: title,
    signedDate,
    notarized: notarization(page),
  };
}

// ── Images over printed values ──────────────────────────────────────────────

const overlaps = (a: BBox, b: BBox) => a[0] < b[0] + b[2] && b[0] < a[0] + a[2] && a[1] < b[1] + b[3] && b[1] < a[1] + a[3];

/**
 * An image drawn over a printed value (a handwritten correction pasted on, a
 * stamp) means the text layer may not be what a person sees. The printed figure
 * is kept — it is what the text says — but it is marked for checking.
 */
function markValuesUnderImages(result: ExtractionResult, pdf: PdfText): void {
  const covers = new Map<number, BBox[]>();
  for (const page of pdf.pages) {
    const area = page.width * page.height;
    const rects = (page.images ?? []).filter((r: Rect) => r.w * r.h < area * 0.6).map((r) => bboxOfRect(page, r));
    if (rects.length) covers.set(page.page, rects);
  }
  if (covers.size === 0) return;
  const under = (e: { page: number | null; bbox?: BBox | null }) => !!e.page && !!e.bbox && (covers.get(e.page) ?? []).some((r) => overlaps(r, e.bbox!));
  const mark = (e: Extracted<unknown>, what: string) => {
    if (e.value === null || !under(e)) return;
    e.confidence = Math.min(e.confidence, 0.5);
    result.notes.push(`Page ${e.page}: an image is drawn over the printed ${what}${e.source ? ` (${e.source})` : ''} — possibly a handwritten correction or a stamp. The printed figure was read; check it against the page.`);
  };
  if (result.payApp) {
    for (const f of CLAIMED_FIELDS) mark(result.payApp.amounts[f], `“${CLAIMED_FIELD_LABEL[f]}”`);
    for (const key of ['applicationNumber', 'periodTo', 'applicationDate'] as const) mark(result.payApp[key] as Extracted<unknown>, key === 'applicationNumber' ? 'application number' : key === 'periodTo' ? 'period end date' : 'application date');
  }
  for (const w of result.waivers ?? []) {
    mark(w.amount, 'waiver amount');
    mark(w.throughDate, 'through date');
  }
  let lines = 0;
  for (const l of result.lines ?? []) {
    if (!under(l)) continue;
    l.confidence = Math.min(l.confidence, 0.5);
    lines++;
  }
  if (lines) result.notes.push(`An image is drawn over ${lines} schedule row${lines === 1 ? '' : 's'}; ${lines === 1 ? 'it is' : 'they are'} marked for checking.`);
}

// ── Entry point ─────────────────────────────────────────────────────────────

const valueAt = (e: Extracted<number>, docType: DocType): ConflictingValue => ({ value: e.value, page: e.page, docType, source: e.source ?? null, bbox: e.bbox ?? null });

export function extractFromText(pdf: PdfText): ExtractionResult {
  const notes: string[] = [];
  const segments = segmentPages(pdf.pages);
  const result: ExtractionResult = { engine: TEXT_ENGINE, segments, notes };
  const pageOf = (n: number) => pdf.pages[n - 1]!;
  const conflicts: ExtractionConflict[] = [];

  const unreadable = pdf.pages.filter(isUnreadable).map((p) => p.page);
  if (unreadable.length > 0) {
    result.unreadablePages = unreadable;
    notes.push(`${unreadable.length === 1 ? 'Page' : 'Pages'} ${unreadable.join(', ')} ${unreadable.length === 1 ? 'is an image' : 'are images'} with no text layer (a scan inserted into the file?). Nothing on ${unreadable.length === 1 ? 'it' : 'them'} was read; key ${unreadable.length === 1 ? 'its' : 'their'} values by hand.`);
  }

  const numbering = pdf.pages.map(printedPageNumber).filter((p): p is PrintedPageNumber => p !== null);
  if (numbering.length > 0) result.pageNumbering = numbering;

  // The first pay application is the one reported. Any other is a conflict a person has to resolve.
  const payAppSegs = segments.filter((s) => s.type === 'pay_application');
  const payAppSeg = payAppSegs[0];
  if (payAppSeg) result.payApp = parsePayApplication(pageOf(payAppSeg.pageStart), notes);
  if (payAppSegs.length > 1 && result.payApp) {
    // The page is where each application starts, whether or not its number could be read.
    const others = payAppSegs.slice(1).map((s) => ({ ...valueAt(applicationNumberOn(pageOf(s.pageStart)), 'pay_application'), page: s.pageStart }));
    conflicts.push({ kind: 'second_pay_application', field: 'applicationNumber', reported: { ...valueAt(result.payApp.applicationNumber, 'pay_application'), page: payAppSeg!.pageStart }, others });
    notes.push(`This file holds ${payAppSegs.length} pay applications (pages ${payAppSegs.map((s) => s.pageStart).join(', ')}). Only the first was read; the schedule pages that follow the others were left out.`);
  }

  // A schedule belongs to the pay application before it (or the first one, if it comes first).
  const sheetSegs = segments.filter((s) => s.type === 'continuation_sheet' && (!payAppSegs[1] || s.pageStart < payAppSegs[1].pageStart));
  if (sheetSegs.length > 0) {
    const lines: ExtractedLine[] = [];
    const totals: Array<NonNullable<SheetPage['total']> & { page: number }> = [];
    let layout: SheetLayout | null = null;
    for (const seg of sheetSegs) {
      for (let n = seg.pageStart; n <= seg.pageEnd; n++) {
        const parsed = parseContinuationPage(pageOf(n), notes, layout);
        lines.push(...parsed.lines);
        if (parsed.total) totals.push({ ...parsed.total, page: n });
        layout = parsed.layout ?? layout;
      }
    }
    result.lines = lines;
    const last = totals[totals.length - 1];
    if (last) {
      result.lineTotals = last.values;
      const grand: ScheduleGrandTotal = { page: last.page, label: last.label || null, bbox: last.bbox, confidence: totals.length > 1 ? Math.min(last.confidence, 0.8) : last.confidence, values: last.values };
      result.scheduleGrandTotal = grand;
    }
    if (lines.length === 0) notes.push('A schedule of values was recognised but no line items could be read from it.');

    // The same application number and totals printed on the schedule.
    if (result.payApp) {
      const reportedNo = result.payApp.applicationNumber;
      const sheetNos = sheetSegs.flatMap((s) => Array.from({ length: s.pageEnd - s.pageStart + 1 }, (_, i) => applicationNumberOn(pageOf(s.pageStart + i)))).filter((e) => e.value !== null);
      const differing = sheetNos.filter((e) => e.value !== reportedNo.value);
      if (reportedNo.value !== null && differing.length > 0) {
        conflicts.push({ kind: 'application_number', field: 'applicationNumber', reported: valueAt(reportedNo, 'pay_application'), others: differing.map((e) => valueAt(e, 'continuation_sheet')) });
        notes.push(`The pay application is numbered ${reportedNo.value}, but the schedule says ${[...new Set(differing.map((e) => e.value))].join(', ')} (page ${differing.map((e) => e.page).join(', ')}).`);
      }
      if (result.scheduleGrandTotal) {
        const g = result.scheduleGrandTotal;
        // Totals the AIA forms define as equal. Retainage is left out: whether the schedule's
        // retainage column includes stored material, a release or a stepped rate varies by form.
        const pairs: Array<[ClaimedField, LineAmountField]> = [
          ['totalCompletedStored', 'total'],
          ['contractSumToDate', 'scheduledValue'],
        ];
        for (const [field, column] of pairs) {
          const mine = result.payApp.amounts[field];
          const theirs = g.values[column];
          if (mine.value === null || theirs === null || theirs === undefined || mine.value === theirs) continue;
          conflicts.push({
            kind: 'total',
            field,
            reported: valueAt(mine, 'pay_application'),
            others: [{ value: theirs, page: g.page, docType: 'continuation_sheet', source: g.label, bbox: g.bbox ?? null }],
          });
          notes.push(`“${CLAIMED_FIELD_LABEL[field]}” is ${mine.source} on the pay application but the schedule’s grand total for that column is different.`);
        }
      }
    }
  }

  const waiverSegs = segments.filter((s) => s.type === 'lien_waiver');
  if (waiverSegs.length > 0) result.waivers = waiverSegs.map((s) => parseWaiver(pageOf(s.pageStart), notes));

  if (conflicts.length > 0) result.conflicts = conflicts;
  markValuesUnderImages(result, pdf);
  return result;
}

/** Locate a money amount on a page so a value from another engine can be tied to a position. */
export function locateAmount(page: PageText, cents: number, nearLabel?: RegExp): { bbox: BBox; source: string } | null {
  const style = styleOf(page);
  let fallback: { bbox: BBox; source: string } | null = null;
  for (const line of page.lines) {
    for (const cell of line.cells) {
      if (!moneyTokens(cell.text).some((t) => t.cents === cents)) continue;
      const hit = { bbox: bboxOf(page, cell), source: cell.text.trim() };
      if (!nearLabel || nearLabel.test(line.text)) return hit;
      fallback ??= hit;
    }
  }
  return fallback;
}

/** Printed page numbering and unreadable pages, for engines that read the page images but not the margins. */
export function pageFacts(pdf: PdfText): { pageNumbering: PrintedPageNumber[]; unreadablePages: number[] } {
  return {
    pageNumbering: pdf.pages.map(printedPageNumber).filter((p): p is PrintedPageNumber => p !== null),
    unreadablePages: pdf.pages.filter(isUnreadable).map((p) => p.page),
  };
}

export { AMOUNT_LABELS };
